export interface Supplier {
  supplierId: number;
  companyId: number;
  supplierName: string;
  contactName: string | null;
  phone: string | null;
  email: string | null;
  address: string | null;
  active: '1' | '0';
  created_At: string;
  updated_at: string | null;
}

export interface SupplierListResponse {
  suppliers: Supplier[];
}

// GET ALL — POST /all_suppliers
export async function getAllSuppliers(companyId: number): Promise<Supplier[]> {
  const res = await fetch(BASE_URL + "/all_suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "companyId": companyId }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  const data: SupplierListResponse = await res.json();
  return data.suppliers ?? [];
}

// CREATE — action: 1
export async function createSupplier(payload: Omit<Supplier, "supplierId" | "created_At" | "updated_at">): Promise<Supplier> {
  const res = await fetch(BASE_URL + "/suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  const data = await res.json();
  if (data.message) { // Backend may return a message instead of the created object on success for some CRUDs
    // In such cases, we might need to refetch the list or return a placeholder/handle differently.
    // For now, assuming successful creation might return a minimal object or require refetch.
    // Per common POS GMO pattern, the /suppliers endpoint should return the object created/updated.
    // If it only returns 'ok', we'd need a strategy to get the full object, or rely on refetching the list.
    return { ...payload, supplierId: Date.now(), created_At: new Date().toISOString(), updated_at: null } as Supplier;
  }
  return data;
}

// UPDATE — action: 2
export async function updateSupplier(id: number, payload: Partial<Omit<Supplier, "supplierId" | "created_At" | "updated_at">>): Promise<Supplier> {
  const res = await fetch(BASE_URL + "/suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "action": 2, "supplierId": id, ...payload }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  const data = await res.json();
  if (data.message) { // Same as create, handle if backend sends only a message
    return { ...payload, supplierId: id } as Supplier;
  }
  return data;
}

