import { IonPage, IonContent, IonHeader, IonToolbar, IonTitle, IonButton, IonIcon, IonList, IonItem, IonLabel, IonFab, IonFabButton, IonModal, IonInput, IonToggle, IonLoading, IonToast, IonAlert, IonInfiniteScroll, IonInfiniteScrollContent, IonCard, IonCardHeader, IonCardSubtitle, IonCardTitle, IonCardContent, IonSearchbar, SearchbarInputEventDetail, ToggleChangeEventDetail, InputInputEventDetail } from '@ionic/react';
import { addOutline, createOutline, trashOutline, peopleOutline, storefrontOutline } from 'ionicons/icons';
import { useUser } from '../contexts/UserContext';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { getAllSuppliers, createSupplier, updateSupplier, deleteSupplier, Supplier } from '../api/supplierApi';
import { useIonViewWillEnter } from '@ionic/react';

import './SupplierPage.css';

// Helper to convert UTC dates to Hermosillo time (UTC-7)
const toHermosillo = (utc: string | undefined | null): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // Subtract 7 hours for UTC-7 (Hermosillo)
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

interface SupplierFormState {
  supplierName: string;
  contactName: string;
  phone: string;
  email: string;
  address: string;
  active: boolean; // Managed as boolean in form, converted to '1'/'0' for API
}

const SupplierPage: React.FC = () => {
  const { companyId } = useUser();

  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [filteredSuppliers, setFilteredSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showCreateEditModal, setShowCreateEditModal] = useState(false);
  const [editingSupplier, setEditingSupplier] = useState<Supplier | null>(null);
  const [formState, setFormState] = useState<SupplierFormState>({
    supplierName: '',
    contactName: '',
    phone: '',
    email: '',
    address: '',
    active: true,
  });
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [supplierToDeleteId, setSupplierToDeleteId] = useState<number | null>(null);
  const [searchText, setSearchText] = useState('');
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);

  // Popover state for Header component
  const [popoverState, setPopoverState] = useState<{ 
    showAlertPopover: boolean; 
    showMailPopover: boolean; 
    event?: Event; 
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) => 
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () => 
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) => 
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () => 
    setPopoverState({ ...popoverState, showMailPopover: false });

  const ITEMS_PER_PAGE = 20; // For infinite scroll

  const fetchSuppliers = async (initialLoad: boolean = true) => {
    if (loading) return;
    setLoading(true);
    setError('');
    try {
      const allSuppliers = await getAllSuppliers(companyId);
      setSuppliers(allSuppliers);
      setFilteredSuppliers(allSuppliers);
      setHasMore(allSuppliers.length > ITEMS_PER_PAGE);
      if (initialLoad) {
        setPage(1);
      }
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar proveedores');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    fetchSuppliers();
  });

  useEffect(() => {
    const lowercasedSearchText = searchText.toLowerCase();
    const filtered = suppliers.filter(s =>
      s.supplierName.toLowerCase().includes(lowercasedSearchText) ||
      (s.contactName && s.contactName.toLowerCase().includes(lowercasedSearchText)) ||
      (s.email && s.email.toLowerCase().includes(lowercasedSearchText))
    );
    setFilteredSuppliers(filtered);
    setPage(1); // Reset page when search text changes
    setHasMore(filtered.length > ITEMS_PER_PAGE);
  }, [searchText, suppliers]);

  const loadMoreItems = (ev: CustomEvent<void>) => {
    const newPage = page + 1;
    const startIndex = (newPage - 1) * ITEMS_PER_PAGE;
    const endIndex = newPage * ITEMS_PER_PAGE;

    if (endIndex < filteredSuppliers.length) {
      setPage(newPage);
    } else {
      setHasMore(false);
    }
    (ev.target as HTMLIonInfiniteScrollElement).complete();
  };

  const handleCreateEditSupplier = async () => {
    setError('');
    setSaving(true);
    try {
      const payload = {
        ...formState,
        active: formState.active ? '1' : '0',
        companyId: companyId,
      };

      if (editingSupplier) {
        await updateSupplier(editingSupplier.supplierId, payload);
      } else {
        await createSupplier(payload);
      }
      setShowCreateEditModal(false);
      setEditingSupplier(null);
      fetchSuppliers(); // Refresh list after create/edit
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar proveedor');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteSupplier = async () => {
    if (supplierToDeleteId === null) return;
    setError('');
    setLoading(true);
    try {
      await deleteSupplier(supplierToDeleteId, companyId);
      fetchSuppliers(); // Refresh list after delete
      setSupplierToDeleteId(null);
    } catch (err) {
      setError((err as Error).message ?? 'Error al eliminar proveedor');
    } finally {
      setLoading(false);
    }
  };

  const openCreateModal = () => {
    setEditingSupplier(null);
    setFormState({
      supplierName: '',
      contactName: '',
      phone: '',
      email: '',
      address: '',
      active: true,
    });
    setShowCreateEditModal(true);
  };

  const openEditModal = (supplier: Supplier) => {
    setEditingSupplier(supplier);
    setFormState({
      supplierName: supplier.supplierName,
      contactName: supplier.contactName || '',
      phone: supplier.phone || '',
      email: supplier.email || '',
      address: supplier.address || '',
      active: supplier.active === '1',
    });
    setShowCreateEditModal(true);
  };

  const handleSearchChange = (e: CustomEvent<SearchbarInputEventDetail>) => {
    setSearchText(e.detail.value!);
  };

  const renderCreateEditModal = () => (
    <IonModal isOpen={showCreateEditModal} onDidDismiss={() => setShowCreateEditModal(false)} className="supplier-modal">
      <IonHeader>
        <IonToolbar>
          <IonTitle>{editingSupplier ? 'Editar Proveedor' : 'Crear Proveedor'}</IonTitle>
          <IonButton slot="end" onClick={() => setShowCreateEditModal(false)}>Cerrar</IonButton>
        </IonToolbar>
      </IonHeader>
      <IonContent className="ion-padding">
        <div className="supplier-form-fields">
          <div className="wizard-field-group">
            <IonInput
              fill="outline"
              label="Nombre del Proveedor *"
              labelPlacement="floating"
              value={formState.supplierName}
              onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, supplierName: e.detail.value! }))}
              className={formState.supplierName === '' ? 'ion-invalid ion-touched' : ''}
              errorText={formState.supplierName === '' ? 'El nombre del proveedor es obligatorio' : undefined}
            />
          </div>
          <div className="wizard-field-group">
            <IonInput
              fill="outline"
              label="Nombre de Contacto"
              labelPlacement="floating"
              value={formState.contactName}
              onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, contactName: e.detail.value! }))}
            />
          </div>
          <div className="wizard-field-group">
            <IonInput
              fill="outline"
              label="Teléfono"
              labelPlacement="floating"
              type="tel"
              value={formState.phone}
              onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, phone: e.detail.value! }))}
            />
          </div>
          <div className="wizard-field-group">
            <IonInput
              fill="outline"
              label="Email"
              labelPlacement="floating"
              type="email"
              value={formState.email}
              onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, email: e.detail.value! }))}
            />
          </div>
          <div className="wizard-field-group">
            <IonInput
              fill="outline"
              label="Dirección"
              labelPlacement="floating"
              value={formState.address}
              onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, address: e.detail.value! }))}
            />
          </div>
          <IonItem lines="none" className="supplier-toggle-item">
            <IonLabel>Activo</IonLabel>
            <IonToggle 
              slot="end" 
              checked={formState.active} 
              onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => setFormState(p => ({ ...p, active: e.detail.checked }))}
            />
          </IonItem>
        </div>
        <IonButton expand="block" onClick={handleCreateEditSupplier} disabled={saving || formState.supplierName === ''}>
          {saving ? <IonSpinner name="dots" /> : (editingSupplier ? 'Guardar Cambios' : 'Crear Proveedor')}
        </IonButton>
      </IonContent>
    </IonModal>
  );

  return (
    <IonPage className="supplier-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Proveedores — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonSearchbar
          placeholder="Buscar por nombre, contacto o email"
          value={searchText}
          onIonInput={handleSearchChange}
          debounce={300}
        />

        <IonList className="supplier-list">
          {filteredSuppliers.slice(0, page * ITEMS_PER_PAGE).map(supplier => (
            <IonCard key={supplier.supplierId} className="supplier-card">
              <IonCardHeader>
                <IonCardSubtitle>
                  {supplier.contactName ? `Contacto: ${supplier.contactName}` : 'Sin Contacto'}
                </IonCardSubtitle>
                <IonCardTitle>{supplier.supplierName}</IonCardTitle>
              </IonCardHeader>
              <IonCardContent>
                <IonItem lines="none" className="supplier-card-item">
                  <IonIcon icon={storefrontOutline} slot="start" className="supplier-icon-detail"/>
                  <IonLabel>
                    <p>Teléfono: {supplier.phone || 'N/A'}</p>
                    <p>Email: {supplier.email || 'N/A'}</p>
