                    <p>Creado: {toHermosillo(supplier.created_At)}</p>
                    {supplier.updated_at && <p>Actualizado: {toHermosillo(supplier.updated_at)}</p>}
                  </IonLabel>
                  <div slot="end" className="supplier-actions">
                    <IonButton fill="clear" color="medium" onClick={() => openEditModal(supplier)}>
                      <IonIcon icon={createOutline} />
                    </IonButton>
                    <IonButton fill="clear" color="danger" onClick={() => { setSupplierToDeleteId(supplier.supplierId); setShowDeleteAlert(true); }}>
